using System;
using System.Collections.Generic;
using System.IO;

namespace Pillion.VisualStudio.Core.Autocomplete;

/// <summary>Why no suggestion is requested.</summary>
public enum SuppressionReason
{
    /// <summary>Not suppressed.</summary>
    None,

    /// <summary>The <c>autocomplete</c> feature flag is off (settings or repository policy).</summary>
    FeatureDisabled,

    /// <summary>The file name marks a generated or designer file (<c>.g.cs</c>, <c>.Designer.cs</c>, <c>*.min.js</c> ...).</summary>
    GeneratedFileName,

    /// <summary>The first lines carry an auto-generated header.</summary>
    GeneratedHeader,

    /// <summary>The file is larger than 1 MB.</summary>
    TooLarge,

    /// <summary>The user switched suggestions off for the language (<c>autocomplete.disabledLanguages</c>).</summary>
    LanguageDisabled,

    /// <summary>A completion list is open with an item selected.</summary>
    CompletionListSelection,
}

/// <summary>
/// The suppression rules of design section 5 (Ghost-text autocomplete): no suggestions in generated and designer
/// files, files over 1 MB, languages the user switched off, and never while a completion list has a selected item.
/// </summary>
public static class SuppressionRules
{
    /// <summary>The largest document, in characters, that gets suggestions (1 MB).</summary>
    public const int MaxDocumentLength = 1024 * 1024;

    /// <summary>How many lines at the top of a file are searched for an auto-generated header.</summary>
    public const int HeaderLines = 12;

    private static readonly string[] GeneratedSuffixes =
    [
        ".g.cs", ".g.i.cs", ".designer.cs", ".g.vb", ".g.i.vb", ".designer.vb", ".min.js", ".min.css", ".min.mjs",
    ];

    private static readonly string[] GeneratedMarkers =
    [
        "<auto-generated", "<autogenerated", "auto-generated", "autogenerated by", "@generated", "do not edit", "generated by a tool",
    ];

    /// <summary>Gets a value indicating whether a file name marks a generated or designer file.</summary>
    /// <param name="path">The file path.</param>
    /// <returns><see langword="true"/> for <c>.g.cs</c>, <c>.g.i.cs</c>, <c>.Designer.cs</c>, <c>*.min.js</c> and their Visual Basic and CSS relatives.</returns>
    public static bool IsGeneratedFileName(string? path)
    {
        if (string.IsNullOrEmpty(path))
        {
            return false;
        }

        string name;
        try
        {
            name = Path.GetFileName(path);
        }
        catch (ArgumentException)
        {
            return false;
        }

        foreach (var suffix in GeneratedSuffixes)
        {
            if (name.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>Gets a value indicating whether the first lines of a file carry an auto-generated header.</summary>
    /// <param name="text">The document text.</param>
    /// <returns><see langword="true"/> when a comment in the first <see cref="HeaderLines"/> lines says the file is generated.</returns>
    public static bool HasGeneratedHeader(IDocumentText text)
    {
        if (text is null)
        {
            throw new ArgumentNullException(nameof(text));
        }

        var lines = Math.Min(HeaderLines, text.LineCount);
        for (var i = 0; i < lines; i++)
        {
            var line = text.GetLineText(i);
            if (line.Length > 400)
            {
                continue;
            }

            var trimmed = line.TrimStart();
            var isComment = trimmed.StartsWith("//", StringComparison.Ordinal)
                || trimmed.StartsWith("/*", StringComparison.Ordinal)
                || trimmed.StartsWith("*", StringComparison.Ordinal)
                || trimmed.StartsWith("#", StringComparison.Ordinal)
                || trimmed.StartsWith("'", StringComparison.Ordinal)
                || trimmed.StartsWith("<!--", StringComparison.Ordinal);
            if (!isComment)
            {
                continue;
            }

            foreach (var marker in GeneratedMarkers)
            {
                if (trimmed.IndexOf(marker, StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    return true;
                }
            }
        }

        return false;
    }

    /// <summary>Gets a value indicating whether a language is in the user's disabled list.</summary>
    /// <param name="languageId">The language identifier.</param>
    /// <param name="disabledLanguages">The identifiers the user switched off.</param>
    /// <returns><see langword="true"/> when the language is listed (case-insensitive).</returns>
    public static bool IsLanguageDisabled(string? languageId, IReadOnlyCollection<string>? disabledLanguages)
    {
        if (string.IsNullOrEmpty(languageId) || disabledLanguages is null || disabledLanguages.Count == 0)
        {
            return false;
        }

        foreach (var disabled in disabledLanguages)
        {
            if (string.Equals(disabled, languageId, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>Evaluates the rules that depend on the document (not the per-keystroke completion list state).</summary>
    /// <param name="path">The file path.</param>
    /// <param name="languageId">The language identifier.</param>
    /// <param name="text">The document text.</param>
    /// <param name="settings">The autocomplete settings.</param>
    /// <returns>The first rule that applies, or <see cref="SuppressionReason.None"/>.</returns>
    public static SuppressionReason EvaluateDocument(string? path, string? languageId, IDocumentText text, AutocompleteSettings settings)
    {
        if (text is null)
        {
            throw new ArgumentNullException(nameof(text));
        }

        if (settings is null)
        {
            throw new ArgumentNullException(nameof(settings));
        }

        if (!settings.Enabled)
        {
            return SuppressionReason.FeatureDisabled;
        }

        if (IsLanguageDisabled(languageId, settings.DisabledLanguages))
        {
            return SuppressionReason.LanguageDisabled;
        }

        if (text.Length > MaxDocumentLength)
        {
            return SuppressionReason.TooLarge;
        }

        if (IsGeneratedFileName(path))
        {
            return SuppressionReason.GeneratedFileName;
        }

        return HasGeneratedHeader(text) ? SuppressionReason.GeneratedHeader : SuppressionReason.None;
    }

    /// <summary>Gets a value indicating whether a completion list state suppresses suggestions.</summary>
    /// <param name="selectedItem">The selected completion item's text, or <see langword="null"/> when no list is open.</param>
    /// <returns><see langword="true"/> when a list has a selected item.</returns>
    public static bool IsCompletionListSelection(string? selectedItem) => !string.IsNullOrEmpty(selectedItem);
}
